import {readFileSync} from 'node:fs';
import {p,code,table,diagram,qa,refs,warn,section} from './lesson-helpers.mjs';
const source=name=>readFileSync(new URL('./examples/testing/'+name,import.meta.url),'utf8');
const vocabulary=(word,meaning)=>`<span class="term" tabindex="0" title="${meaning}">${word}</span>`;
const javaRun=p('Runnable Java 17+ examples live in <a href="examples/testing/pom.xml">the shared Maven project</a>. From the repository root:')+code('mvn -B -f v4/examples/testing/pom.xml test');
const inventory=source('src/main/java/academy/testing/Inventory.java');
const examples=source('src/test/java/academy/testing/InventoryExamplesTest.java');
const properties=source('src/test/java/academy/testing/InventoryPropertiesTest.java');
const contract=JSON.parse(readFileSync(new URL('./examples/contracts/cancellation.openapi.json',import.meta.url),'utf8'));
export const developmentApproaches=[
{
slug:'atdd',title:'ATDD',heading:'Agree on acceptance before building the feature',
intro:'Turn “reserve stock safely” into concrete acceptance examples, implement one slice, and decide what evidence is sufficient to accept it. Connect business agreement to executable Java checks.',
definition:'Acceptance test-driven development brings business, development and testing perspectives together to define acceptance examples before implementing the corresponding behavior. Those examples guide development and provide evidence for accepting the change.',
prerequisites:'Start with <a href="bdd.html#example-map">BDD example mapping</a>. Basic Java helps with the runnable example; no Cucumber experience is needed.',
outcome:'Write acceptance examples that expose ambiguity, choose their execution boundary and distinguish a passing domain example from evidence that the deployed feature is acceptable.',
sections:[
section('problem','Start with a decision to accept',p('A shop asks for “stock reservation that never oversells.” The developer subtracts a quantity from available stock. QA checks that ten minus one is nine. The business expects a buyer asking for all ten units to succeed and two buyers racing for the last unit never both to succeed. Everyone can approve a different interpretation unless the examples come first.')+p('An acceptance example is like agreeing on the delivery contents before signing a receipt. It gives the team an observable condition for saying this slice is ready. It should describe a valuable outcome and its exceptions, rather than prescribe private method calls or a particular framework.')+p('For this lesson, reserve reduces available units immediately when enough units exist. Zero and negative quantities are invalid; an unaffordable request is rejected without changing stock. Reservation expiry, payment and duplicate command handling are separate requirements. Naming these exclusions prevents a small example from becoming an accidental promise about the entire checkout.')),
section('reasoning-path','Connect ATDD, BDD and TDD',table(['Practice','Focus in this story','Useful output'],[['ATDD','What evidence will let us accept this stock-reservation slice?','Agreed acceptance examples before implementation.'],['BDD','Which rules and concrete cases create shared understanding?','A common language and discovered questions.'],['TDD','What small behavior should the implementation support next?','Fast failing checks, implementation and refactoring.']])+p('The practices overlap substantially. Teams need not perform three ceremonies or maintain three copies of every example. Use the acceptance conversation to settle the outer behavior, then smaller tests to evolve and diagnose its implementation. A test written afterward can still supply regression evidence, but did not drive that original decision.')+diagram(['Agree on examples','Implement one behavior slice','Check acceptance evidence'],'When a question appears, return to agreement rather than silently rewriting the expected result.')),
section('acceptance-table','Make the examples discriminate',table(['Available before','Requested','Expected decision','Available after'],[['10','1','Accept','9'],['10','10','Accept: equality is allowed','0'],['10','11','Reject: insufficient stock','10'],['0','1','Reject: empty stock','0'],['10','0 or negative','Invalid request','10']])+p('The equality row distinguishes greater-than from greater-than-or-equal. The rejected row checks preservation of state as well as a false result. Invalid quantity is a separate category: it is not simply another insufficient-stock case. A response code will be decided at the HTTP boundary later.')+p('Ask about the missing cases while the change is cheap. Does the stock represent physical units or an available projection? Is reservation an immediate deduction, an expiring hold, or a promise from a remote warehouse? Who owns the last-unit decision? An unanswered authority question is a blocker to the overselling guarantee, even when the arithmetic examples are easy to automate.')),
section('worked','Run the agreed examples',p('The table becomes a parameterized JUnit test. The remaining tests check invalid input and two sequential buyers. This runs against a small in-memory Inventory object, not a live service. Read both assertions in each row: the decision and resulting stock jointly describe the rule.')+code(examples)+p('These checks use the <a href="ddd.html#worked">Inventory domain example</a>. They are executable acceptance examples for that domain behavior only. The sequential last-unit test does not run two transactions at once. A real overselling promise still needs a database concurrency mechanism and a test of the actual competing writes.')+javaRun),
section('vertical-slice','Deliver one thin slice',p('Start with one owner reserving one product. Connect input validation, the application command, an authoritative conditional update and an observable result. Keep the first slice small enough to demonstrate to the person who owns the rule. Then add invalid input, rejection and the competing buyer with explicit expectations.')+table(['Layer','Evidence needed','Typical omission'],[['Domain','The agreed quantity/state examples pass.','Testing only accepted requests.'],['HTTP/security','Identity, quantity parsing and error mapping follow the contract.','A test principal with unlimited privileges.'],['Database','Competing reservations cannot both spend the same unit.','Using only an in-memory fake.'],['Operations','Unknown results and stuck reservations can be found and recovered.','Treating a timeout as proof of rejection.']])+p('Do not require the team to automate every unknown before learning anything. A short spike may reveal the real warehouse contract. Record the finding and settle the acceptance rule before treating the implementation as complete. A prototype is useful evidence about feasibility, not permission to hide an unresolved business decision.')),
section('commit-evidence','Accept the right guarantee',code('-- Conceptual SQL for a single authoritative stock row:\nUPDATE stock SET available = available - :quantity\nWHERE tenant_id = :tenant AND sku = :sku\n  AND :quantity > 0 AND available >= :quantity;\n-- Inspect affected rows and commit before claiming durable acceptance.')+p('This illustrates where the arithmetic decision belongs when requests compete. Zero affected rows needs interpretation under the service contract, including nonexistent products and authorization. The database engine, transaction isolation and data model still need verification. This SQL is a teaching fragment, not the implementation used by the runnable Java tests.')+p('If the write commits but the response is lost, the buyer has an unknown outcome. Before retrying, the system needs stable command identity and a durable way to discover the original reservation. Add an example for that timeline if repeat-safe requests are in scope. An acceptance suite that excludes it cannot justify a retry-safety claim.')),
section('review-ci','Keep acceptance useful in CI',p('Store the agreed examples near the code and review rule changes with their owner. Run fast domain checks on every change, then adapter and database checks at the boundaries they substantiate. A small deployed acceptance flow should use the built artifact and representative configuration.')+p('For an asynchronous reservation, acceptance and completion need separate observations. Replace a fixed sleep with bounded polling of the reservation status, reporting the last observed state on failure. Choose the deadline from the agreed test environment, and make cleanup safe for committed fixtures. Never make a green run depend on a previous scenario creating the next scenario’s stock.')+table(['A check fails','Investigate first','Avoid'],[['Expected rule changed','Product decision and old-client impact.','Editing the expected result simply to obtain green.'],['Only parallel CI fails','Fixture collisions, transaction timing and shared resources.','Disabling all concurrency coverage.'],['Environment unavailable','Dependency health and test scope.','Reporting a skipped acceptance flow as a pass.']])),
section('pitfalls','Keep the claim honest',p('ATDD earns its cost when acceptance is ambiguous or crosses roles. It is less useful as a second paperwork layer for a settled internal helper. A compact table with meaningful counterexamples often communicates more than a long feature file.')+warn('Business acceptance is not exhausted by a green test suite. Accessibility, security, capacity, recovery and user usefulness may need other evidence. State which checks were automated, against what boundary, and which decisions remain open.')+p('<strong>Practice:</strong> add an expiring reservation. Agree what happens exactly at expiry, after payment succeeds late and after a duplicate release. Write one acceptance example for each disagreement before selecting a timer or queue.')),
section('interview','Explain acceptance with evidence',qa([
['Foundational','Does ATDD require Gherkin?',p('No. A table, readable code or another shared notation can express the examples. The important order is agreement before implementation, followed by useful checks.')],
['Foundational','How does it differ from UAT?',p('User acceptance testing commonly evaluates an implemented product. ATDD uses acceptance examples to guide development beforehand; later user evaluation can still reveal unmet needs.')],
['Intermediate','Why include the exact-stock row?',p('It distinguishes the intended inclusive boundary. A test that only asks for one unit from ten cannot detect rejecting equality.')],
['Intermediate','Can an in-memory example prove no overselling?',p('It can prove selected domain decisions and sequential state changes. It cannot establish the correctness of concurrent database transactions or multiple service instances.')],
['Advanced','What is the acceptance result after a lost commit response?',p('Unknown until the original operation can be reconciled. Define stable identity and a durable outcome lookup; a timeout alone is not a rejected reservation.')],
['Advanced','What would you include in a release decision?',p('The agreed examples, boundary-specific evidence, known exclusions, operational recovery and owner approval of remaining risks. A passing example count is not the release argument.')]
])),
section('references','Read and apply',refs([['https://agilealliance.org/glossary/atdd/','Agile Alliance: ATDD','the collaborative test-first acceptance practice.'],['https://cucumber.io/docs/bdd/example-mapping/','Example Mapping','a way to discover rules and counterexamples.']])+p('<a href="examples/testing/src/test/java/academy/testing/InventoryExamplesTest.java">Download the executable acceptance examples</a>. Continue to <a href="contract-first.html">contract-first development</a> to specify their HTTP boundary.'))
]},
{
slug:'ddd',title:'Domain-Driven Design',heading:'Model the business before splitting the services',
intro:'Follow stock reservation across Sales, Inventory and Billing. Learn the language, context boundaries and invariants first, then use aggregates, value objects and domain events with clear transaction limits.',
definition:'Domain-driven design develops software models in close collaboration with domain experts. It makes the business language and model boundaries explicit, and uses those models to guide code and architectural decisions.',
prerequisites:'Read <a href="microservices.html">service boundaries</a> and understand a local transaction. The <a href="atdd.html#acceptance-table">reservation examples</a> supply a concrete business rule.',
outcome:'Draw a context map, identify a consistency boundary and explain why a domain model, database schema and microservice deployment need not have identical boundaries.',
sections:[
section('problem','One word can mean different things',p('Sales calls an order confirmed when the customer finishes checkout. Inventory calls it reserved when units have been held. Billing calls a payment captured when the provider reports a completed capture. A shared status string called CONFIRMED cannot safely express all three facts.')+p('Think of departments using different dictionaries for the same word. DDD makes those dictionaries explicit and asks the people who know the work to refine the model with developers. Start by listening to actual decisions and exceptions. Do not begin by generating classes called Entity, Aggregate and Repository.')+p('Our shop’s Inventory model owns available stock and reservation decisions. Sales owns purchase intention and order lifecycle. Billing owns payment/refund facts. A customer-facing order view can combine those facts without becoming the authority that changes all of them in one local transaction.')),
section('reasoning-path','Move from language to boundaries',table(['Term','Plain meaning','Shop example'],[['Domain','The area of activity the software serves.','Selling and fulfilling purchases.'],['Subdomain','A problem area within that activity.','Stock reservation or tax calculation.'],['Bounded context','A boundary within which a model and its terms have defined meanings.','Inventory defines available and reserved units.'],['Ubiquitous language','The model’s language used consistently in discussions and code within its context.','reserve, release and expire rather than arbitrary status updates.']])+p('A subdomain describes a problem area; a bounded context describes a model boundary. Their relationship is a design decision, not a rule requiring one service per noun. A bounded context can initially be a module in one process. Separating deployables later adds network and operational costs without automatically improving the model.')+diagram(['Sales: purchase intention','Inventory: reservation authority','Billing: payment authority'],'Relationships between models require explicit contracts; the arrows are not a shared transaction.')),
section('context-map','Map ownership and translation',table(['Relationship','Contract in this shop','Failure question'],[['Sales → Inventory','Reserve units under a stable reservation identity.','If the response is lost, how does Sales find the reservation?'],['Inventory → Sales','ReservationAccepted or ReservationRejected facts.','Can duplicates or older facts regress an order?'],['Sales → Billing','Request payment for the same purchase intention.','What if payment succeeds after the reservation expires?'],['Billing → provider','Translate the provider’s statuses and identifiers.','Which outcomes remain unknown after timeout?']])+p('An anti-corruption layer translates an external model into the local one. For example, a warehouse status ALLOCATED might mean a non-expiring commitment there while our RESERVED state is an expiring hold. Copying the external enum into the order model hides that disagreement. Translation must decide semantics, not merely rename a JSON field.')+p('Record who owns each contract, whether the downstream team can influence it and how breaking changes are coordinated. A diagram of boxes without ownership or failure behavior is not enough to guide independent changes.')),
section('building-blocks','Use tactical patterns selectively',table(['Pattern','Purpose','Example or caution'],[['Entity','Keep identity despite changing attributes.','Reservation R7 remains R7 when its status changes.'],['Value object','Represent meaning through values and validation.','Quantity or Money with explicit units/currency.'],['Aggregate root','Control changes within an invariant boundary.','A stock authority prevents spending the same available unit twice.'],['Repository','Load/save domain roots through a domain-oriented boundary.','It does not make remote writes part of one database transaction.'],['Domain service','Express a domain operation that belongs to no single entity/value.','Avoid moving every entity’s behavior into a giant service class.']])+p('Choose an aggregate because facts must change consistently together. Putting all products, customers and payments under Order creates a huge lock and persistence graph. Conversely, scattering every field into an independently written object can destroy the invariant. Ask which updates must be decided together and how contention will be bounded.')+p('Framework annotations are an implementation choice. A model can contain JPA mappings deliberately, or use an adapter that maps persistence records to domain objects. The important question is whether the choice makes domain rules clear and preserves the intended transaction boundary.')),
section('worked','Put a small invariant in code',p('This runnable class isolates the core behavior of one inventory authority: no accepted reservation makes available units negative. A full aggregate would also need product identity, reservation identity, versioning and persistence. Those are intentionally absent from this arithmetic example.')+code(inventory)+p('The method validates the request before mutation and refuses an unaffordable reservation without changing state. A caller cannot bypass the rule by calling setAvailable. That improves local encapsulation, but the object is not thread-safe and two database copies can still disagree. Encapsulation in Java is not a distributed concurrency mechanism.')+javaRun+p('The <a href="atdd.html#worked">acceptance examples</a> exercise selected rules. The <a href="property-based-testing.html#worked">property tests</a> explore broader input combinations.')),
section('transactions-events','Keep events and commits distinct',p('Suppose Inventory accepts R7 and wants to announce it. Update stock, record the reservation and append an outbox fact in the same local transaction. Publishing after a commit without a durable outbox can lose the notification; publishing before commit can announce a reservation that rolls back.')+code('Local Inventory transaction:\n  recognize reservationId R7 or validate a new intention\n  conditionally reserve units\n  record R7 and its outcome\n  append ReservationAccepted(eventId E7, reservationId R7)\nCommit\n\nRelay may deliver E7 more than once.\nSales consumes it using its own duplicate/version rules.')+p('A domain event expresses a meaningful occurrence. An integration event is a deliberate published contract between contexts; it need not expose every internal event or entity field. Include stable identity and the information readers need, while preserving the freedom to change the internal model.')+p('A saga coordinates progress across contexts through local commits and explicit recovery. A compensating release is another business operation; it cannot make a remote capture never have happened. Define the late-success policy, especially when payment succeeds after stock expiry.')),
section('boundaries-in-practice','Evolve the model with evidence',p('Start with a modular monolith when one team and one deployment can support the workload. Enforce module APIs and prevent direct writes to another context’s tables even if the database is shared. Later extraction should follow ownership, scaling and release needs rather than a desire to maximize service count.')+table(['Signal','Investigate','Possible change'],[['Every checkout change touches Inventory internals','Leaking model or unclear command contract.','Expose a domain command and explicit outcome.'],['One stock aggregate becomes hot','Contention and the true inventory unit of ownership.','Partition independent stock authorities, preserving cross-location semantics.'],['One term has conflicting meanings','A context boundary or translation is missing.','Split meanings and publish a translation contract.'],['Simple lookup code is buried in abstractions','Patterns exceed the domain complexity.','Use a simpler implementation for that supporting capability.']])+p('Not all parts of a system deserve the same modeling effort. Invest deeply where business distinctions and change create risk. A simple administrative lookup can remain simple; it need not imitate the core reservation model’s structure.')),
section('pitfalls','Check the model under failure',p('A useful model makes failure decisions explainable. If two buyers compete for the last unit, which authority serializes the decision? If Sales retries R7, which durable record recognizes it? If the provider’s payment state is unknown, which local state communicates uncertainty instead of inventing success or failure?')+warn('An aggregate is not a promise that arbitrary distributed operations are atomic. Define the real persistence and concurrency boundary, then test it. A bounded context is also not automatically one microservice, one database or one team.')+p('<strong>Practice:</strong> map a subscription purchase across Catalog, Subscription and Billing. Define the meaning of active in each context, the authority for each fact and one translation that would be unsafe as a shared enum.')),
section('interview','Defend the model',qa([
['Foundational','Is DDD a test-first approach?',p('No. It concerns business modeling and explicit model boundaries. It can work with BDD, ATDD and TDD, which provide complementary feedback.')],
['Foundational','Entity versus value object?',p('An entity has identity that persists through change. A value object represents a value with meaningful validation/equality; it is usually treated as immutable.')],
['Intermediate','Does each bounded context need its own service?',p('No. A context can be a module. Independent deployment is a separate decision with operational and distributed-consistency costs.')],
['Intermediate','Why not share the warehouse enum everywhere?',p('The same label can carry different promises. Translate external meaning into the local model and make uncertainty explicit rather than spreading an accidental dependency.')],
['Advanced','How do you choose an aggregate boundary?',p('Identify the invariant and the facts that must change consistently together, then evaluate contention, loading and persistence. Avoid both a giant graph and boundaries that split one atomic decision.')],
['Advanced','What happens when payment succeeds after reservation expiry?',p('The local commits cannot be undone as if nothing happened. A coordinated workflow needs a product policy such as re-reservation or refund, stable identity and durable recovery.')]
])),
section('references','Read and apply',refs([['https://www.domainlanguage.com/wp-content/uploads/2016/05/DDD_Reference_2015-03.pdf','Eric Evans: DDD Reference','the primary pattern reference.'],['https://www.domainlanguage.com/wp-content/uploads/2016/04/GettingStartedWithDDDWhenSurroundedByLegacySystemsV1.pdf','DDD around legacy systems','introducing model boundaries incrementally.']])+p('Continue with <a href="contract-first.html">contract-first development</a> to publish an interface between models, and <a href="consistency.html">consistency</a> to defend the transaction boundary.'))
]},
{
slug:'contract-first',title:'Contract-First Development',heading:'Agree on the interface before both sides implement it',
intro:'Design an order-cancellation HTTP contract before the client and server diverge. Work through schemas, error semantics, security, compatibility and a realistic implementation-verification pipeline.',
definition:'Contract-first development reviews and versions an interface agreement before implementing its participants. Machine-readable schemas describe the wire format; explicit semantics and executable checks connect that agreement to actual behavior.',
prerequisites:'Read <a href="index.html">API Design</a> and the <a href="bdd.html#example-map">BDD cancellation examples</a>. JSON and basic HTTP are enough to begin.',
outcome:'Review a contract for both syntax and meaning, identify breaking changes and distinguish schema validation from business or integration correctness.',
sections:[
section('problem','Two teams implement different agreements',p('The frontend sends POST /orders/O7/cancel and expects 204. The backend implements POST /orders/O7/cancellations and returns a JSON outcome. Both teams can pass local tests while integration fails immediately. Agreeing on the boundary first prevents this avoidable mismatch.')+p('Think of choosing the plug and socket dimensions before manufacturing both sides. A shared drawing helps independent work, but it does not prove the wiring is safe. In an API, the drawing includes path, method, headers and schemas; the wiring includes authorization, durable effects and failure semantics.')+p('For our cancellation example, a 200 result means the synchronous operation has a durable cancellation outcome under the documented identity policy. A claimed order returns conflict. If the design instead accepts background work, the contract must describe 202, a status resource and terminal outcomes; changing only the status code would be incomplete.')),
section('reasoning-path','Start from observable behavior',diagram(['Agree on examples and semantics','Review a versioned contract','Implement and verify both sides'],'A generated stub accelerates implementation; it does not prove the implementation honors the agreement.')+table(['Contract part','Question to settle','Example'],[['Addressing','Which operation represents the intention?','POST /orders/{orderId}/cancellations.'],['Input','What must every caller supply?','Authenticated identity and a scoped Idempotency-Key.'],['Success','What fact is durable at the response?','Cancellation completed or a recognized repeated cancellation.'],['Failure','What may the caller safely do next?','Conflict means too late; timeout means outcome unknown.'],['Evolution','Which existing clients must keep working?','Explicit compatibility/support policy, including generated clients.']])+p('Collaborate with the domain owner and actual consumers. A schema created from an internal DTO can be a useful starting point, but generated documentation after implementation is not evidence that the interface was agreed beforehand.')),
section('worked','Read a concrete OpenAPI contract',p('This operation comes from a complete, downloadable <a href="examples/contracts/cancellation.openapi.json">OpenAPI 3.1.1 teaching document</a>. It is an interface artifact, not a running endpoint. The response outcome deliberately maps the domain decision CANCEL to the public state label CANCELLED.')+code(JSON.stringify(contract.paths['/orders/{orderId}/cancellations'],null,2))+p('A bearer security scheme describes how a credential is presented. It does not validate a token or enforce order ownership. The server must validate the credential under the intended issuer/audience policy and check resource-level permission before changing state. The 403/404 descriptions also require an agreed disclosure policy.')),
section('semantics','Write what the schema cannot prove',table(['Concern','Agreement beyond the schema','Required implementation evidence'],[['Retry identity','Scope keys by principal/tenant and operation; define payload mismatch and retention.','Duplicate and concurrent request tests against durable storage.'],['Durability','Define the commit represented by 200.','Read committed state through a separate transaction after response.'],['Ownership','A caller may act only on permitted orders.','Cross-customer request is denied and changes no state.'],['Unknown outcome','Timeout is not proof of rollback.','Original-key replay or a documented status lookup.'],['Information disclosure','Decide whether forbidden/not-found resources are distinguishable.','Consistent policy in lookup and error mapping.']])+p('Do not encode a promise only in an example payload and assume every tool enforces it. Examples illustrate intended values; schemas define structural constraints; prose/state-machine rules define additional behavior. Review those pieces together and state which checks validate each one.')+p('If a provider cannot support your desired retry policy, contract-first work has exposed a design conflict early. Resolve it through an operation resource, workflow or different acceptance point rather than publishing a contract the system cannot uphold.')),
section('parallel-work','Use mocks without trusting them blindly',p('After review, the client can develop against a contract-based mock while the provider implements the endpoint. A useful mock produces agreed success and failure shapes, including missing optional fields and documented error responses. It should not become a hand-edited second specification.')+code('Contract review → versioned specification\n  Client: real API client + specification-based mock\n  Provider: implementation + request/response verification\n  CI: schema validation + compatibility diff + semantic examples\n  Release: verify supported deployed client/provider combinations')+p('Generated server interfaces can enforce method signatures but not transaction behavior. Generated clients can also make compatibility assumptions, such as exhaustive enum handling. Compile and exercise representative clients; do not assume that adding a response enum member is harmless because the JSON remains valid.')+p('Tools such as Specmatic can connect specifications to mocks and verification, subject to their supported dialects and configuration. Choose and pin tools for the project’s specification version. The downloadable artifact here is not presented as having run through a full live-provider verification suite.')),
section('compatibility','Review changes in both directions',table(['Change','Likely risk','Review action'],[['Require a new request field','Old clients cannot produce it.','Add a compatible default or migrate/version deliberately.'],['Remove/rename a response field','Existing readers lose a dependency.','Observe usage and preserve overlap during migration.'],['Add an optional response field','Usually additive, but strict readers may reject it.','Check actual client parsing and tolerance.'],['Add an outcome enum value','Exhaustive readers may fail.','Define unknown-value behavior or a version transition.'],['Change 200 to 202','The meaning of completion changes.','Treat as a semantic contract change, not cosmetic schema editing.']])+p('Compatibility depends on a direction and a population. Can an old client send to the new provider? Can a new client run against the old provider during rollout? Which versions are still supported? A green final-state integration test says little about mixed versions during deployment.')+p('For events, also consider retained history, delayed messages and replay. A new reader may need to understand old facts long after the old writer is gone. A live HTTP compatibility diff does not establish that event-history requirement.')),
section('spring-ci','Verify the implementation boundary',p('In a Java/Spring service, keep transport DTO validation separate from the domain policy. Verify JSON binding, required headers, error envelopes, configured security and request limits at the HTTP boundary. Verify state transitions and unique identities at the repository/transaction boundary.')+p('CI should fail on malformed specifications and unintended incompatible changes. It should also run selected semantic examples: the last allowed cancellation, claimed-order conflict, duplicate identity and denied owner. A schema validator will not discover that an error response was returned after the database already changed.')+table(['Evidence','Proves something about','Does not establish'],[['Specification parses/validates','Document structure and supported constraints.','A deployed endpoint exists.'],['Response matches schema','Selected wire representation.','Correct order, tenant or committed result.'],['Provider semantic test','A selected behavior in the configured application.','All client compatibility.'],['Deployed smoke check','Built artifact/routing for a critical path.','Every failure or workload.']])),
section('pitfalls','Keep one maintained agreement',p('Avoid maintaining an OpenAPI file, a separate mock JSON library and controller annotations that disagree. Choose the authoritative artifact and verify generated or derived outputs. Review intentional changes with affected consumers and define a retirement process for obsolete behavior.')+warn('A machine-readable contract is a powerful agreement about an interface. It is not a proof of end-to-end security, useful business behavior, capacity or resilience. Keep those claims attached to their own evidence.')+p('<strong>Practice:</strong> change cancellation to asynchronous processing. List the required changes to acceptance meaning, response schema, status lookup, retry behavior and client UX before editing the OpenAPI file.')),
section('interview','Defend the agreement',qa([
['Foundational','Contract-first versus code-first?',p('Contract-first agrees the boundary before implementation; code-first derives a description from code. Either can maintain useful contracts, but the timing and collaboration differ.')],
['Foundational','Does OpenAPI enforce authorization?',p('It can describe security requirements. Actual credential validation and resource policy remain implementation responsibilities and need tests.')],
['Intermediate','Why can a schema-compatible change break clients?',p('Semantics, enum handling, strict parsing, ordering, limits and status meanings can change without a structurally invalid payload.')],
['Intermediate','Can teams develop in parallel with a mock?',p('Yes, if the mock derives from the agreed contract and both real participants are verified. A passing mock test alone proves neither provider behavior nor real integration.')],
['Advanced','How do you review a rollout?',p('Check old/new client-provider combinations, supported versions, durable data changes and the removal schedule. Verify the overlap rather than only the final new-new pair.')],
['Advanced','What does a response validator miss after a timeout?',p('Whether the original effect committed and how the caller can recover it. That needs stable operation identity and durable outcome semantics beyond shape validation.')]
])),
section('references','Read and apply',refs([['https://spec.openapis.org/oas/v3.1.1.html','OpenAPI 3.1.1','the dialect used by the downloadable example.'],['https://docs.specmatic.io/contract_driven_development.html','Specmatic contract-first workflow','specifications connected to mocks and verification.']])+p('Compare <a href="consumer-contract-testing.html">consumer-driven contract testing</a>, which captures particular consumers’ expectations rather than relying only on one full provider specification.'))
]},
{
slug:'consumer-contract-testing',title:'Consumer-Driven Contract Testing',heading:'Prove that a provider still speaks its consumers’ language',
intro:'Follow an Order client and Billing provider through consumer tests, published interactions, provider verification and release decisions. Learn what Pact-style contracts cover and where business integration tests remain necessary.',
definition:'Consumer-driven contract testing captures the interactions a consumer depends on and verifies that a provider can satisfy them. Consumer-side execution and provider-side verification form complementary evidence for specific participant versions.',
prerequisites:'Read <a href="contract-first.html">contract-first development</a> and understand the difference between a real API client and a hand-written mock response.',
outcome:'Design a useful consumer interaction, explain provider states and matching, and make a version-aware deployment argument without claiming full end-to-end correctness.',
sections:[
section('problem','A green mock can tell the wrong story',p('Order needs Billing to return payment P7 with status CAPTURED. Its local mock returns that string, so the client tests pass. Billing renames the field from status to state, but its own endpoint tests also pass. Production fails when the real client reads a missing field.')+p('The problem is not that either team lacks tests. Their tests assert independent assumptions. A consumer contract connects the expectations exercised by the actual client to a check of the provider. Think of checking that a supplier still delivers the part dimensions your assembly uses, rather than assuming its internal quality checks cover your dependency.')+p('This is particularly useful for independently released services. It does not mean every internal method needs a published contract, or that provider business rules can be delegated to its consumers.')),
section('reasoning-path','Follow the two-sided evidence',diagram(['Consumer exercises real client','Publish interaction contract','Provider verifies that interaction'],'Record both application versions; a mock-only pass is incomplete evidence.')+table(['Step','Important detail','Failure detected'],[['Consumer test','Invoke the production HTTP client against a controlled contract mock.','Wrong request construction or response parsing.'],['Contract publication','Attach immutable consumer version and branch/release metadata.','Missing/stale expectations can be identified.'],['Provider verification','Prepare the named state, call the provider and match the response.','Provider no longer satisfies the interaction.'],['Deployment check','Use verification evidence for the versions in the target environment.','A new-new pass hides an old consumer still deployed.']])+p('Do not manually construct the same request in a test while leaving the real client unused. That can generate a plausible contract without testing the code that production executes. Keep business orchestration outside a focused client contract test so failures remain attributable.')),
section('worked','Specify one real dependency',code('Illustrative interaction, not a runnable Pact file:\nConsumer: Order service\nProvider: Billing service\nProvider state: payment P7 belongs to tenant T7 and is captured\n\nRequest:\n  GET /payments/P7\n  Authorization: a valid test credential for T7\n\nExpected response:\n  200 application/json\n  id: exact value P7\n  status: exact value CAPTURED (the branch Order needs)\n  amountMinor: an integer matching the agreed money representation\n\nConsumer assertion:\n  invoke the real BillingClient against the contract mock\n  assert the parsed result drives the captured-payment branch')+p('The exact captured status matters because Order branches on it. For unrelated generated identifiers or timestamps, suitable type/format matchers reduce brittleness. Matchers are not a license to accept any value for a field whose meaning determines the consumer’s action.')+p('This lesson shows the protocol rather than a copy-paste Pact-JVM runner. Framework APIs and setup depend on the pinned Pact/JUnit versions, HTTP client, authentication adapter and provider lifecycle. No Pact Broker or live Billing provider is included in the Java example project.')),
section('matching','Be strict about needs, loose about accidents',table(['Field/detail','Useful expectation','Overconstraint or blind spot'],[['Payment identifier','Match P7 when the client requests P7.','Accepting any identifier can hide a wrong-resource response.'],['Status used for branching','Explicit captured/failed cases the client supports.','A string matcher alone misses an unsupported status.'],['Extra response fields','Tolerate additions when the real parser tolerates them.','Exact whole-body matching can reject safe additions.'],['Timestamp','Format and relevant semantics where supported.','An arbitrary fixed time makes unrelated changes break verification.'],['Money','Integer/decimal representation, units and required fields.','A numeric type alone does not establish currency or accounting correctness.']])+p('Include relevant negative interactions such as not found or a documented conflict if the consumer handles them. Do not reproduce the provider’s entire functional suite through the contract. The contract should expose what this consumer needs, while provider tests remain responsible for the rules producing those outcomes.')+p('Request matching and response matching can have different tolerance rules. Read the selected Pact specification/tool’s matching behavior rather than assuming an extra request field and an extra response field are equivalent changes.')),
section('provider-states','Prepare state without scripting a journey',p('A provider state names the starting facts required by an interaction, such as payment P7 is captured. Provider verification arranges those facts deterministically. It should not require a previous contract test to have created P7 or rely on uncontrolled production data.')+p('Use isolated test storage or appropriately controlled fixtures, and run the configured provider boundary that serves the interaction. Replacing the whole application with another hand-written response merely compares two mocks. Replacing an external payment processor can be reasonable when the intended verification scope is the Billing API, but label that scope.')+table(['Problem','Consequence','Correction'],[['State setup depends on scenario order','Parallel or selected verification fails.','Make every state self-contained.'],['Credentials expire during verification','Compatibility failures become environment noise.','Use a controlled test-auth configuration with explicit limits.'],['A test-state endpoint is deployed openly','Test setup becomes a security capability.','Keep setup isolated from production exposure.'],['Provider state over-specifies internal tables','Refactoring breaks contracts without changing behavior.','Name domain facts; hide fixture mechanics behind the state handler.']])),
section('release-matrix','Verify the versions that actually meet',p('Suppose Order v12 and Billing v8 are deployed. Billing v9 passes a contract published by Order v13, but v12 still needs a removed field. The v13-v9 result does not justify deploying v9 while v12 remains live.')+table(['Consumer','Provider','Result','Deployment implication'],[['Order v12','Billing v8','Pass','Existing supported pair.'],['Order v12','Billing v9','Fail','Do not infer safety from the newer consumer’s success.'],['Order v13','Billing v9','Pass','Only this pair’s interaction evidence is established.'],['Order v12','Billing v10','Unknown','Needs verification or an explicit policy for missing evidence.']])+p('A Pact Broker can record contract versions, verification results and deployments; can-i-deploy evaluates the relevant matrix. Publish meaningful immutable application versions and record what reaches each environment. Incorrect metadata makes a sophisticated gate answer the wrong question.')+p('Treat unknown verification as unknown. A team can have an explicit workflow for pending contracts or early development, but that policy must not silently promote unverified production compatibility. Retire old consumer versions using actual support/deployment evidence.')),
section('messages-limits','Separate compatibility from delivery',p('For asynchronous integration, a consumer can exercise its message handler with the agreed message while the producer verifies the event it generates. This checks payload compatibility at selected boundaries. It does not send the message through the real broker, validate retention or prove acknowledgement safety.')+table(['Claim','Suitable evidence','Contract check alone?'],[['Consumer parses ReservationAccepted','Real handler/client plus representative message.','Useful for that interface dependency.'],['Producer creates the expected message','Producer verification at its output boundary.','Useful for the selected representation.'],['Duplicate delivery has one effect','Durable receipt/effect transaction and repeated delivery.','No.'],['Old events replay safely','History/version policy and replay tests.','No.'],['Checkout completes through all services','Selected real integration/deployed flow.','No.']])+p('A syntactically compatible CAPTURED response can still report the wrong tenant’s payment. Keep authorization and provider business correctness tests. Contract testing reduces a class of integration failures; it does not remove the need to reason about authority, identity or failure recovery.')),
section('pitfalls','Use contracts for real boundaries',p('Avoid publishing contracts from tests that never call the production client, matching every incidental field or copying the provider’s entire functional suite. Those patterns increase maintenance without protecting the dependency that matters.')+warn('A successful contract verification is evidence for selected interactions and versions under the verification setup. It is not proof of production networking, security, throughput or complete business correctness.')+p('<strong>Practice:</strong> design a contract for Subscription consuming Billing’s invoice response. Name two fields that need exact semantic values, two that can use tolerant matchers, and a provider business rule that belongs outside this contract suite.')),
section('interview','Explain the evidence chain',qa([
['Foundational','Who writes the consumer contract?',p('The consumer team captures its actual client/handler needs. The provider verifies it; cooperation is still needed to agree on supported behavior.')],
['Foundational','Is a hand-written mock enough?',p('No. A mock can drift from the provider. Provider verification supplies the complementary evidence, and the consumer test must exercise the real consuming code.')],
['Intermediate','What is a provider state?',p('A named prerequisite fact for an interaction, arranged independently by the verifier. It is not a required sequence of earlier user actions.')],
['Intermediate','Why avoid exact matching every field?',p('Incidental fields can turn safe provider changes into failures. Be precise about what the consumer depends on and tolerant where its real behavior is tolerant.')],
['Advanced','Both newest versions pass. Is deployment safe?',p('Not necessarily. Check the consumer/provider versions still deployed or supported in the destination environment, including mixed-version rollout.')],
['Advanced','Can message contracts prove exactly-once effects?',p('No. Payload compatibility is separate from broker delivery and the consumer’s durable effect boundary. Test duplicates, crashes and replay using those mechanisms.')]
])),
section('references','Read and apply',refs([['https://docs.pact.io/consumer','Pact consumer tests','testing the real API client and choosing meaningful expectations.'],['https://docs.pact.io/pact_broker/can_i_deploy','Pact deployment matrix','version-aware compatibility decisions.'],['https://docs.pact.io/','Pact documentation','provider verification and message-contract workflows.']])+p('Return to <a href="contract-first.html">contract-first development</a> to compare a shared full specification with per-consumer expectations. Both approaches can coexist with deliberate ownership.'))
]},
{
slug:'property-based-testing',title:'Property-Based Testing',heading:'Test a rule across many generated cases',
intro:'Move from a few stock-reservation examples to generated invariants, constrained inputs and small counterexamples. Run Java properties and learn their limits around models, overflow, randomness and concurrency.',
definition:'Property-based testing checks general statements about behavior over many generated inputs. A useful failure report identifies a counterexample; shrinking attempts to simplify it while preserving the failure.',
prerequisites:'Read <a href="tdd.html#test-design">TDD test design</a> and the <a href="atdd.html#acceptance-table">stock examples</a>. Understand Java assertions and the meaning of an invariant.',
outcome:'Write a meaningful property, design valid generators and interpret a failure without confusing sampled cases with a proof of all possible behavior.',
sections:[
section('problem','Four examples leave a large input space',p('The reservation table covers ten units and an empty store. Production receives quantities ranging across many values. One example per familiar case cannot explore every combination of current stock and requested units. A property asks what must remain true across that wider space.')+p('Imagine checking that a weighing scale conserves weight across many combinations of objects. You do not need to know every reading in advance to say adding an object must not make the combined weight lower. Similarly, an accepted reservation must not create stock, and a rejected one must leave stock unchanged.')+p('Keep concrete examples for important business boundaries. Generated cases complement the named equality, empty-stock and invalid-input cases; they do not replace the conversation that established what the correct rule means.')),
section('reasoning-path','Separate the property from its generator',table(['Part','Question','Inventory example'],[['Property','What general relation must hold?','Available stock never becomes negative or increases after reserve.'],['Generator','Which inputs and distributions do we explore?','Nonnegative stock and positive quantities in a declared range.'],['Oracle','Why is the expected relation valid?','A reservation consumes units or changes nothing.'],['Shrinker','Can a failing case become easier to understand?','Reduce a large failing pair to a small boundary case.'],['Seed','How is this generated run reproduced?','Record the seed, generator configuration and library version.']])+p('Avoid an expected result that simply repeats the production condition. Independent relations often reveal more. Conservation, monotonicity, round trips under a defined domain and idempotency of a completed operation can be useful properties. Each needs assumptions: compress/decompress may be a round trip, while a lossy normalization is not reversible.')+diagram(['Generate relevant inputs','Exercise behavior and assert a property','Shrink and preserve a counterexample'],'A generated failure becomes a concrete regression example after diagnosis.')),
section('worked','Run two Java properties',p('The project pins QuickTheories 0.26 and runs it inside ordinary JUnit tests. These properties exercise the same Inventory class as the acceptance table. Fixed seeds keep this teaching run reproducible; they are not a claim that these are the latest library versions or that two seeds cover the domain.')+code(properties)+javaRun+p('The first property checks bounds and conservation for accepted operations, and unchanged stock for rejection. It does not insist every affordable request is accepted: an implementation that always rejects would pass that property. The named acceptance examples and the second property provide additional evidence. This is why the strength of the oracle matters as much as the number of generated inputs.')+p('The second property compares two affordable sequential reservations with one combined reservation. Its generators deliberately bound the sum to avoid overflow. It relies on our simple unit-reservation rules; a bulk discount, per-order minimum or reservation fee could make the analogous property invalid in a different domain.')),
section('generators','Design inputs that reach the interesting behavior',table(['Generator decision','Good reason','Risk to inspect'],[['Restrict stock to nonnegative values','Valid-state properties have a clear domain.','Invalid constructor input still needs separate checks.'],['Generate positive quantities','Exercise valid requests without excessive discarded cases.','Zero and negative cases are excluded, so add them explicitly.'],['Bias toward equality and adjacent values','Find boundary defects quickly.','Uniform random generation may rarely reach a particular boundary.'],['Generate structured domain values','Reach valid combinations intentionally.','A generator that excludes difficult states can hide defects.'],['Bound arithmetic intentionally','Avoid accidental overflow in the test oracle.','The bounded test proves nothing about untested extreme values.']])+p('Prefer constructing valid inputs directly over filtering almost everything out. Heavy assumptions can produce a passing run with very little useful exploration. Track discarded cases and distributions where the tool supports it. Generate invalid inputs separately when rejection is part of the contract.')+p('For full-range arithmetic, decide whether overflow should be rejected or represented through a larger numeric type. Add named cases around Long.MAX_VALUE and Long.MIN_VALUE as appropriate. A test that overflows its own expected value can approve the same bug as the implementation.')),
section('shrinking','Read a small failure carefully',code('Illustrative failure, not a captured run:\nProperty: an affordable reservation succeeds\nOriginal case: stock=73492, quantity=73492\nSimplified counterexample: stock=1, quantity=1\nPossible cause: quantity >= available was used for rejection\nExpected business rule: equality is allowed')+p('Shrinking searches for a simpler failing case under the generator and shrink strategy. It does not guarantee the mathematically smallest example or diagnose the cause automatically. Reproduce the case, understand the rule, then add a clear named regression test if it communicates a valuable boundary.')+p('Preserve the seed, tool version and relevant generator settings. A seed alone may not reproduce the same sequence after generator or framework changes. The actual input is often the most durable diagnostic artifact, especially when an external state or timing schedule contributed to the failure.')),
section('stateful','Generate sequences when order matters',p('A single reserve call cannot establish a whole reservation lifecycle. A richer model might include reserve, release, expire and repeat command. Generate sequences against a simple reference model, checking allowed transitions and conservation after every step.')+code('Conceptual stateful model, not in the runnable example:\ninitial available = 10\nreserve(R7, 3) → available 7, R7 active\nrepeat reserve(R7, 3) → available 7\nrelease(R7) → available 10, R7 released\nrepeat release(R7) → available 10\nInvariant: active holds + available = total stock\nAssumptions: no replenishment, consumption or loss in this model')+p('The reference model must be simpler or independently specified enough to avoid copying the same defect. Define how rejected commands, unknown outcomes and replay relate to the model. If a release can race a successful shipment, the valid state machine needs a business decision before property generation can resolve it.')+p('Sequential generated commands do not explore concurrent database interleavings. For concurrency, combine a justified consistency mechanism with controlled competing transactions, history checking or another appropriate verification technique.')),
section('ci-feedback','Use randomness as evidence, not noise',p('Use a stable, quick property set for routine feedback and an intentionally varied run to explore other seeds when useful. Record failing seeds and counterexamples as artifacts. Give larger runs a clear budget so an expensive search cannot stall every change indefinitely.')+table(['Failure source','Useful diagnosis','Wrong response'],[['A real counterexample','Replay the input and inspect the violated rule.','Change the seed until green.'],['Environment dependency','Isolate clocks, external state and fixtures.','Assume every generated failure is a random flake.'],['Bad property assumption','Review it with the domain owner.','Modify production code to satisfy an invalid theorem.'],['Generator excludes edge cases','Add structure/bias and explicit examples.','Increase sample count without improving input relevance.']])+p('The included Maven project runs two fixed-seed properties with 1,000 generated examples each. These are sampled sequential checks over bounded inputs. Report that scope explicitly rather than claiming complete coverage or mathematical proof.')),
section('pitfalls','Challenge the oracle',p('A property that output is non-null is rarely enough. An always-empty result can pass many weak properties. Add properties or examples that distinguish doing useful work from simply avoiding obvious failure. Conversely, avoid asserting a relation that is only accidentally true for the current implementation.')+warn('Property-based testing explores a defined input space with a defined oracle. A flawed property or generator can miss every important defect even after millions of cases.')+p('<strong>Practice:</strong> define properties for pagination without duplicates under a stated snapshot model. Explain why the same property can fail legitimately on a changing live dataset. Then write a generator that includes equal sort keys.')),
section('interview','Explain generated evidence',qa([
['Foundational','Example-based versus property-based tests?',p('An example names a concrete expected case. A property describes a relation checked across generated cases. Useful suites often combine both.')],
['Foundational','What is shrinking?',p('An attempt to simplify a failing generated case while preserving the failure. It makes diagnosis easier, but does not guarantee a globally minimal counterexample.')],
['Intermediate','Why can an always-reject implementation pass a property?',p('If the property only asserts no negative stock or no change on rejection, rejecting everything satisfies it. Add liveness/useful-behavior examples and stronger independent relations.')],
['Intermediate','Is a fixed seed enough to reproduce a failure?',p('Not always after generator or library changes. Preserve the actual counterexample, relevant versions and configuration too.')],
['Advanced','Do generated sequential tests prove concurrent safety?',p('No. They exercise generated inputs and orderings within the stated execution model. Database races require evidence at the concurrency boundary.')],
['Advanced','How do you avoid mirroring the implementation?',p('Use independently justified invariants, metamorphic relations or a simpler model, and check important concrete examples. Review whether the oracle can share the same defect.')]
])),
section('references','Read and apply',refs([['https://github.com/quicktheories/QuickTheories','QuickTheories','the Java generator, assertion and seed APIs used here.'],['https://hypothesis.works/articles/what-is-property-based-testing/','Hypothesis: property-based testing','the underlying idea beyond a particular Java library.']])+p('<a href="examples/testing/src/test/java/academy/testing/InventoryPropertiesTest.java">Download the property tests</a>. Use <a href="mutation-testing.html">mutation testing</a> to challenge whether your assertions notice meaningful code changes.'))
]},
{
slug:'mutation-testing',title:'Mutation Testing',heading:'Check whether your tests notice the wrong behavior',
intro:'Deliberately alter a stock rule and see which tests fail. Run a scoped PIT report, interpret surviving mutants and learn why mutation scores, coverage and business correctness are different claims.',
definition:'Mutation testing introduces small program changes and runs tests to see whether they detect the altered behavior. It evaluates aspects of test sensitivity against selected mutation operators, rather than proving the implementation satisfies all requirements.',
prerequisites:'Read <a href="tdd.html#test-design">test design</a> and the <a href="atdd.html#worked">stock examples</a>. The runnable report uses Maven, JUnit and PIT.',
outcome:'Explain killed, surviving and uncovered mutants, investigate a useful survivor and adopt mutation testing without gaming a percentage or treating every mutation as a real bug.',
sections:[
section('problem','Executed code can still be weakly tested',p('A reservation test calls reserve(1) on ten units and checks only that no exception was thrown. Coverage reports that the subtraction line ran. Now replace subtraction with addition: the test may stay green while stock is created from nothing.')+p('Mutation testing asks whether the checks sound the alarm when a selected small mistake is introduced. It is like testing a smoke alarm with a controlled signal rather than merely confirming the light is on. The controlled signal represents a class of faults, not every possible fire.')+p('Our example uses Inventory and its named acceptance tests. The report is deliberately scoped to that class, so readers can inspect each change. It does not measure the entire textbook, all Java examples or the correctness of a deployed inventory service.')),
section('reasoning-path','Separate coverage from sensitivity',table(['Evidence','Question answered','Important limit'],[['Line coverage','Did the test execute this line?','Execution can happen without a meaningful assertion.'],['Branch coverage','Were selected control-flow alternatives exercised?','The asserted outcome can still be wrong or incomplete.'],['Mutation result','Did a test detect a selected artificial code change?','The operator set and tests cover only selected fault classes.'],['Business acceptance','Does the behavior meet the agreed rule?','Requires a correct rule and suitable observation boundary.']])+diagram(['Run a green baseline','Mutate selected code','Run relevant tests and inspect results'],'A failing baseline invalidates mutation analysis; establish reliable ordinary tests first.')+p('PIT mutates compiled Java bytecode and selects relevant tests using coverage information. The report maps results back to source. The displayed source-level interpretation can be approximate, so inspect the operator and observable effect rather than assuming every line description is literal source editing.')),
section('worked','Run a scoped PIT report',p('The shared Maven project pins PIT 1.18.2 and its JUnit 5 plugin 1.2.2. This configuration mutates Inventory and uses InventoryExamplesTest as the detecting suite. The property tests still run in ordinary Maven tests; they are deliberately outside this small mutation scope.')+code('mvn -B -f v4/examples/testing/pom.xml test\nmvn -B -f v4/examples/testing/pom.xml test-compile \\\n  org.pitest:pitest-maven:mutationCoverage\n\n# Open locally after the command completes:\n# v4/examples/testing/target/pit-reports/index.html')+code('<targetClasses>\n  <param>academy.testing.Inventory</param>\n</targetClasses>\n<targetTests>\n  <param>academy.testing.InventoryExamplesTest</param>\n</targetTests>\n<timestampedReports>false</timestampedReports>')+p('CI runs the analysis and retains its HTML/XML report as an artifact. It does not impose a universal mutation-score threshold or promise that every generated mutant is killed. Read the actual report from the run; example calculations below are hypothetical and are not claimed report results.')+p('<a href="examples/testing/pom.xml">Download the full pinned configuration</a> and <a href="examples/testing/src/main/java/academy/testing/Inventory.java">the target source</a>.')),
section('interpretation','Interpret each result before changing code',table(['Result','Meaning','Next step'],[['Killed','At least one relevant test detects the altered program.','Inspect whether the failure is meaningful rather than incidental infrastructure breakage.'],['Survived','The selected tests did not detect this mutation.','Check missing assertions, missing cases and possible equivalent behavior.'],['No coverage','No selected test executes the mutated location.','Decide whether the path belongs in scope and add relevant tests if needed.'],['Timed out','The mutation exceeded the configured execution budget.','Inspect the operator and baseline stability; do not equate every timeout with a useful assertion.'],['Tool/run error','The analysis could not establish a normal result.','Fix infrastructure or compatibility before drawing conclusions.']])+p('A survivor is a question, not an automatic instruction to add a test. The altered code may be equivalent for every valid input, or the code itself may be unnecessary. Removing redundant production code can be better than writing a test for an unobservable implementation detail.')+p('A killed mutant also has limits. A test may fail because an error message changed while the business outcome is wrong in both versions. Review the quality of the detecting assertion, especially for critical rules.')),
section('boundary-example','Investigate a boundary mutation',code('Illustrative source-level change:\nOriginal: if (quantity > available) return false;\nMutation: if (quantity >= available) return false;\n\nTest case: available=10, quantity=10\nAgreed result: accepted=true, available=0\nMutated result: accepted=false, available=10')+p('The equality row in InventoryExamplesTest distinguishes these versions. If the row were absent and all successful quantities were comfortably below stock, a boundary mutation could survive. The useful response is an example for the agreed rule, not an assertion about a private branch variable.')+table(['Hypothetical survivor','Possible gap','Useful investigation'],[['Subtraction behaves as addition','Only response success is asserted.','Assert remaining stock and conservation.'],['Rejection condition is removed','No insufficient-stock example.','Add a rejected request and check unchanged state.'],['Invalid-input guard disappears','Only positive quantities tested.','Check zero/negative input and no mutation.'],['A redundant null guard changes','Valid inputs cannot distinguish the versions.','Determine equivalence; simplify or document narrowly.']])+p('These are illustrative fault hypotheses. The exact mutants generated depend on the PIT version, operators, compiler and source. Do not write a report claiming a particular survivor without running and reading the configured analysis.')),
section('scores','Use percentages with a declared denominator',p('For an illustrative report with 20 killed, 5 survived and 5 uncovered mutants, the simple killed/all total is 20/30, about 67%. Excluding uncovered mutants gives 20/25, or 80%, which answers a different question. Tools can distinguish mutation coverage from test strength and classify other outcomes differently.')+p('Always inspect the report’s definitions and included statuses. A percentage without target classes, operator set, excluded code and baseline is hard to interpret. Comparing two teams’ scores can be meaningless if one targets a small pure policy and the other includes large generated adapters.')+table(['Temptation','Why it misleads','Better decision'],[['Set 100% as a universal target','Equivalent or irrelevant mutants can consume effort.','Review high-risk survivors and set a justified project policy.'],['Exclude every difficult class','Score improves while evidence shrinks.','Record exclusions and the alternative assurance.'],['Treat a rising score as fewer production defects','Fault model and requirements may be incomplete.','Combine sensitivity with acceptance and boundary evidence.'],['Use only the summary number','One missed money/security rule can matter more than many trivial kills.','Inspect critical mutants individually.']])),
section('ci-adoption','Start small and keep the baseline trustworthy',p('Begin with a stable domain policy or calculation where failures are cheap and meaningful. Run ordinary tests first, then mutation analysis on the target. Preserve reports so reviewers can see whether the change improves assertions or merely changes scope.')+p('For larger repositories, use a bounded changed-code or critical-module strategy where supported, and schedule broader analysis separately if it earns its cost. Record plugin/compiler/JDK versions. A slow, flaky baseline amplifies costs when many mutated executions repeat it.')+p('Do not run real payments or notifications inside mutation tests. An altered guard can remove protection against side effects. Keep test collaborators isolated and safe, and use dedicated integration evidence for real external contracts. The included Inventory target has no network or persistence side effects.')+p('When adding thresholds, choose how new uncovered code, equivalent mutants and tool errors are handled. A failed analysis should be visible; silently skipping the mutation lane is not the same as meeting the policy.')),
section('pitfalls','Avoid tests that only defend implementation',p('A test that asserts the exact private helper call order can kill mutants while making harmless refactoring expensive. Favor business-visible outcomes and invariants. Mutation analysis should help discover weak evidence, not force the implementation to remain structurally frozen.')+warn('Mutation testing challenges a finite set of artificial changes. It cannot identify missing requirements, prove authorization or discover every possible race. Keep independent business, integration and concurrency evidence.')+p('<strong>Practice:</strong> temporarily remove the exact-stock acceptance row, run the scoped report and inspect whether a relevant boundary mutation survives. Restore or improve the test based on the observed report; do not assume a particular operator is always generated.')),
section('interview','Defend the report',qa([
['Foundational','What does killed mean?',p('A selected test detects the mutated program. Inspect the actual failure before treating it as strong evidence for the business rule.')],
['Foundational','Why is line coverage insufficient?',p('A line can execute while its result is never asserted. A deliberate arithmetic or boundary change may still pass the suite.')],
['Intermediate','Must every survivor lead to a new test?',p('No. Investigate equivalent behavior, redundant code, scope and missing meaningful assertions. Some survivors warrant simplification or a documented exclusion instead.')],
['Intermediate','Can two mutation percentages be compared directly?',p('Only with compatible scope, operators, status definitions and exclusions. Different denominators and target code can make the comparison misleading.')],
['Advanced','Why start from a green, deterministic baseline?',p('Otherwise ordinary failures and timing noise contaminate repeated mutated runs, making the detecting evidence unreliable and analysis costly.')],
['Advanced','Can mutation testing prove concurrent reservation safety?',p('No. It evaluates selected program changes under selected tests. Concurrency guarantees still need a sound authoritative write mechanism and evidence about competing executions.')]
])),
section('references','Read and apply',refs([['https://pitest.org/quickstart/maven/','PIT Maven setup','target selection, reports and configuration.'],['https://pitest.org/quickstart/mutators/','PIT mutation operators','the fault models behind generated changes.'],['https://github.com/pitest/pitest-junit5-plugin','PIT JUnit 5 plugin','test-engine integration and version compatibility.']])+p('Combine <a href="atdd.html">agreed acceptance examples</a>, <a href="property-based-testing.html">generated properties</a> and mutation analysis: agreement establishes the intended rule, generation broadens cases and mutation challenges sensitivity.'))
]}
];
